const cb = $json.callback_query;
const parts = cb.data.split('|');
const prefix = parts[0];
let result = {
  chat_id: cb.message.chat.id,
  message_id: cb.message.message_id,
  callback_query_id: cb.id
};

if (prefix === 'rlk' || prefix === 'no') {
  result.tipe_callback = 'realokasi';
  result.action = prefix;
  result.pending_id = parts[1];
} else if (prefix === 'acc') {
  result.tipe_callback = 'rekening';
  result.rekening_pilihan = parts[1];
  result.pending_id = parts[2];
} else if (prefix === 'katy' || prefix === 'katn') {
  result.tipe_callback = 'kategori';
  result.approve = (prefix === 'katy');
  result.pending_id = parts[1];
}

return [{ json: result }];

const pending = $('Ambil Data Pending Realokasi').first().json;
const dari = $('Ambil Budget Sumber').first().json;
const ke = $input.first().json;
const jumlah = pending.property_jumlah;

return [{
  json: {
    dari_page_id: dari.id,
    dari_limit_baru: (dari.property_limit_bulanan || 0) - jumlah,
    ke_page_id: ke.id,
    ke_limit_baru: (ke.property_limit_bulanan || 0) + jumlah,
    jumlah,
    dari_kategori: pending.property_dari_kategori,
    ke_kategori: pending.property_ke_kategori,
    chat_id: $('Parse Callback Router').first().json.chat_id,
    pending_id: pending.id
  }
}];

const pending = $('Ambil Data Pending Rekening (Callback)').first().json;
const rekening = $('Parse Callback Router').first().json.rekening_pilihan;
const chat_id = $('Parse Callback Router').first().json.chat_id;

return [{
  json: {
    deskripsi: pending.property_deskripsi,
    tanggal: pending.property_tanggal,
    jumlah: pending.property_jumlah,
    tipe: pending.property_tipe,
    kategori: pending.property_kategori,
    rekening: rekening,
    sumber: pending.property_sumber || 'Chat',
    chat_id: chat_id
  }
}];

