const res = $input.first().json;
const cand = res.candidates && res.candidates[0];
if (!cand || !cand.content || !cand.content.parts) {
  throw new Error('Gemini gak ngasih output valid. finishReason: ' + (cand ? cand.finishReason : 'tidak ada candidate'));
}
const raw = cand.content.parts[0].text;
const cleaned = raw.replace(/```json|```/g, '').trim();
const data = JSON.parse(cleaned);
if (data.jenis === 'transaksi') data.sumber = 'Chat';
return [{ json: data }];

const d = $input.first().json;
return [{
  json: {
    deskripsi: d.deskripsi,
    tanggal: d.tanggal,
    jumlah: d.jumlah,
    tipe: d.tipe,
    kategori: d.kategori,
    rekening: d.rekening,
    sumber: d.sumber || 'Chat',
    chat_id: $('Telegram Trigger').first().json.message.chat.id
  }
}];

const transaksi = $('Gabungkan Data Transaksi').first().json;
const saldoPage = $input.first().json;
const saldoLama = saldoPage.property_saldo_sekarang;

let saldoBaru;
if (transaksi.tipe === 'Expense') {
  saldoBaru = saldoLama - transaksi.jumlah;
} else {
  saldoBaru = saldoLama + transaksi.jumlah;
}

return [{
  json: { ...transaksi, saldo_lama: saldoLama, saldo_baru: saldoBaru, saldo_page_id: saldoPage.id }
}];

const transaksi = $('Hitung Saldo Baru').first().json;
const budgetItems = $input.all();

if (transaksi.tipe !== 'Expense' || budgetItems.length === 0) {
  return [{ json: { ...transaksi, warning_level: 'none' } }];
}

const budget = budgetItems[0].json;
const limit = budget.property_limit_bulanan || 0;
const terpakai = (budget.property_terpakai_bulan_ini || 0) + transaksi.jumlah;
const persen = limit > 0 ? (terpakai / limit) * 100 : 100;

let warningLevel = 'none';
if (persen >= 90) warningLevel = '90';
else if (persen >= 80) warningLevel = '80';

return [{
  json: { ...transaksi, limit, terpakai, persen: Math.round(persen), warning_level: warningLevel, budget_page_id: budget.id }
}];

const income = $('Hitung Saldo Baru').first().json.jumlah;
const budgets = $input.all().map(i => i.json);
const totalLimitLama = budgets.reduce((sum, b) => sum + (b.property_limit_bulanan || 0), 0);

if (totalLimitLama === 0) {
  return [{ json: { skip: true } }];
}

return budgets.map(b => {
  const proporsi = (b.property_limit_bulanan || 0) / totalLimitLama;
  const tambahan = Math.round(income * proporsi);
  return {
    json: {
      page_id: b.id,
      kategori: b.property_kategori,
      limit_lama: b.property_limit_bulanan || 0,
      limit_baru: (b.property_limit_bulanan || 0) + tambahan,
      tambahan
    }
  };
});

const items = $input.all().map(i => i.json);
const chatId = $('Hitung Saldo Baru').first().json.chat_id;
const jumlahIncome = $('Hitung Saldo Baru').first().json.jumlah;

let text = '💰 Income Rp' + jumlahIncome.toLocaleString('id-ID') + ' masuk! Budget bulanan ikut nambah proporsional:\n\n';
items.forEach(it => {
  text += '- ' + it.kategori + ': Rp' + it.limit_lama.toLocaleString('id-ID') + ' -> Rp' + it.limit_baru.toLocaleString('id-ID') + ' (+Rp' + it.tambahan.toLocaleString('id-ID') + ')\n';
});

return [{ json: { chat_id: chatId, text } }];

const current = $('Cek Ambang Budget').first().json;
const allBudgets = $input.all().map(i => i.json);

if (current.warning_level === 'none') {
  return [{ json: { ...current, has_realokasi_option: false } }];
}

const kandidat = allBudgets
  .filter(b => b.property_kategori !== current.kategori)
  .map(b => ({
    kategori: b.property_kategori,
    page_id: b.id,
    sisa: (b.property_limit_bulanan || 0) - (b.property_terpakai_bulan_ini || 0)
  }))
  .filter(b => b.sisa > 0)
  .sort((a, b) => b.sisa - a.sisa);

if (kandidat.length === 0) {
  return [{ json: { ...current, has_realokasi_option: false } }];
}

const sumber = kandidat[0];
const topUp = Math.min(Math.round(current.limit * 0.2), sumber.sisa);

return [{
  json: {
    ...current, has_realokasi_option: topUp > 0,
    sumber_kategori: sumber.kategori, sumber_page_id: sumber.page_id,
    sumber_sisa: sumber.sisa, jumlah_realokasi: topUp
  }
}];

const items = $input.all().map(i => i.json);
let total = 0;
let text = '💰 Saldo lo saat ini:\n\n';
items.forEach(it => {
  const nama = it.property_nama || it.name || '(tanpa nama)';
  const saldo = it.property_saldo_sekarang || 0;
  total += saldo;
  text += '- ' + nama + ': Rp' + saldo.toLocaleString('id-ID') + '\n';
});
text += '\nTotal semua rekening: Rp' + total.toLocaleString('id-ID');

return [{ json: { chat_id: $('Telegram Trigger').first().json.message.chat.id, text } }];
